CREATE POLICY streams_owner_update_boundary ON public.streams AS RESTRICTIVE FOR UPDATE TO authenticated USING (host_id = auth.uid()) WITH CHECK (host_id = auth.uid());
CREATE POLICY streams_owner_delete_boundary ON public.streams AS RESTRICTIVE FOR DELETE TO authenticated USING (host_id = auth.uid());
CREATE POLICY stage_owner_insert_boundary ON public.stage_participants AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK (public.is_stream_host(auth.uid(), stream_id) OR (user_id = auth.uid() AND stage_role IN ('listener','green_room')));
CREATE POLICY stage_owner_update_boundary ON public.stage_participants AS RESTRICTIVE FOR UPDATE TO authenticated USING (public.is_stream_host(auth.uid(), stream_id) OR user_id = auth.uid()) WITH CHECK (public.is_stream_host(auth.uid(), stream_id) OR (user_id = auth.uid() AND stage_role IN ('listener','green_room')));
CREATE POLICY stage_owner_delete_boundary ON public.stage_participants AS RESTRICTIVE FOR DELETE TO authenticated USING (public.is_stream_host(auth.uid(), stream_id) OR user_id = auth.uid());
CREATE POLICY queue_owner_update_boundary ON public.stream_queue AS RESTRICTIVE FOR UPDATE TO authenticated USING (public.is_stream_host(auth.uid(), stream_id) OR user_id = auth.uid()) WITH CHECK (public.is_stream_host(auth.uid(), stream_id) OR user_id = auth.uid());
CREATE POLICY queue_owner_delete_boundary ON public.stream_queue AS RESTRICTIVE FOR DELETE TO authenticated USING (public.is_stream_host(auth.uid(), stream_id) OR user_id = auth.uid());
CREATE POLICY hands_owner_update_boundary ON public.raise_hand_requests AS RESTRICTIVE FOR UPDATE TO authenticated USING (public.is_stream_host(auth.uid(), stream_id) OR user_id = auth.uid()) WITH CHECK (public.is_stream_host(auth.uid(), stream_id) OR user_id = auth.uid());
CREATE POLICY hands_owner_delete_boundary ON public.raise_hand_requests AS RESTRICTIVE FOR DELETE TO authenticated USING (public.is_stream_host(auth.uid(), stream_id) OR user_id = auth.uid());
CREATE POLICY messages_owner_delete_boundary ON public.stream_messages AS RESTRICTIVE FOR DELETE TO authenticated USING (public.is_stream_host(auth.uid(), stream_id) OR user_id = auth.uid());
CREATE OR REPLACE FUNCTION public.keep_profile_live_owner() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN IF NEW.host_id IS DISTINCT FROM OLD.host_id THEN RAISE EXCEPTION 'Profile live ownership cannot be transferred'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER keep_profile_live_owner BEFORE UPDATE OF host_id ON public.streams FOR EACH ROW EXECUTE FUNCTION public.keep_profile_live_owner();